# news-image-01: writes the 13 Nov 2026 world-news summary image to entry.png.
# Deterministic: the JPEG bytes are embedded below as base64 and decoded
# at runtime. Stdlib only, no network, no randomness, no model calls.
import base64, os
DATA = ""
OUT = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
os.makedirs(OUT, exist_ok=True)
with open(os.path.join(OUT, "entry.png"), "wb") as f:
    f.write(base64.b64decode(DATA))
